import * as T from './vendor/three.module.js';
import {createHenMotion} from './hen-motion.js';
import {snapshot,restore,solveLimb,rotateWorld} from './idle-rig-math.js';
import {crawlContact,validateCrawlSample} from './crawl-state.js';
const V=(x=0,y=0,z=0)=>new T.Vector3(x,y,z),Q=()=>new T.Quaternion();
// The hen hunkers onto her feathered breast and shuffles, rather than adopting
// a mammal's horizontal pelvis or treating wing tips as firearm hands.
export function createHenCrawlMotion(worker,profile){
 const original=snapshot(worker.bones),rootState={p:worker.root.position.clone(),q:worker.root.quaternion.clone(),s:worker.root.scale.clone()};worker.root.position.set(0,0,0);worker.root.quaternion.identity();worker.root.updateMatrixWorld(true);const base=createHenMotion(worker);base.restore();
 const pelvis=worker.bones.find(b=>b.name==='pelvis'),tail=new T.Bone();tail.name='crawl tail';pelvis.add(tail);tail.position.copy(pelvis.worldToLocal(V(-.20,.94,0)));worker.root.updateMatrixWorld(true);const skeleton=new T.Skeleton([...base.skeleton.bones,tail]);skeleton.calculateInverses();for(const mesh of worker.parts){mesh.bind(skeleton);if(mesh.name==='upright tail fan'){const a=mesh.geometry.attributes;for(let i=0;i<a.position.count;i++){a.skinIndex.setXYZW(i,skeleton.bones.indexOf(tail),0,0,0);a.skinWeight.setXYZW(i,1,0,0,0);}a.skinIndex.needsUpdate=a.skinWeight.needsUpdate=true;}}
 const bones=Object.fromEntries(skeleton.bones.map(b=>[b.name,b])),bind=snapshot(skeleton.bones),rest=new Map(skeleton.bones.map(b=>[b,b.getWorldPosition(V())])),stride=.20;
 // The apron hem follows the folded thighs instead of becoming a rigid board
 // under the breast. The hen adapter restores the original weights on teardown.
 for(const mesh of worker.parts.filter(p=>p.name==='continuous apron')){const a=mesh.geometry.attributes;for(let i=0;i<a.position.count;i++){const fold=.9*(1-T.MathUtils.smoothstep(a.position.getY(i),.48,.86)),side=T.MathUtils.smoothstep(a.position.getZ(i),-.12,.12);a.skinIndex.setXYZW(i,skeleton.bones.indexOf(bones.pelvis),skeleton.bones.indexOf(bones['thigh -1']),skeleton.bones.indexOf(bones['thigh 1']),0);a.skinWeight.setXYZW(i,1-fold,fold*(1-side),fold*side,0);}a.skinIndex.needsUpdate=a.skinWeight.needsUpdate=true;}
 const feet=[-1,1].map(side=>{const a=bones['thigh '+side],b=bones['shank '+side],c=bones['foot '+side],index=skeleton.bones.indexOf(c),inverse=c.matrixWorld.clone().invert();let low=Infinity;for(const mesh of worker.parts){const attr=mesh.geometry.attributes;for(let i=0;i<attr.position.count;i++){let weight=0;for(let k=0;k<4;k++)if(attr.skinIndex.getComponent(i,k)===index)weight+=attr.skinWeight.getComponent(i,k);if(weight>.8)low=Math.min(low,V().fromBufferAttribute(attr.position,i).applyMatrix4(mesh.matrixWorld).applyMatrix4(inverse).y);}}return {side,a,b,c,height:.006-low};});
 let height=.31,disposed=false,state;
 function raw(distance,{blend=1,heading=0,position=V()}={}){
  base.restore();restore(bind);worker.root.quaternion.identity();const phase=((distance/stride%1)+1)%1,shift=Math.sin(phase*Math.PI*2)*blend;bones.pelvis.position.set(-.06,height,.008*shift);bones.pelvis.rotation.z=-1.25;bones.breast.rotation.z=.12;bones.head.rotation.z=1.10;bones.head.rotation.y=.025*shift;tail.rotation.z=2.15;worker.root.updateMatrixWorld(true);
  const footStates=feet.map(l=>{const contact=crawlContact(distance,stride,l.side===1?0:.5,{lift:.024}),target=V(-.10+contact.x,l.height+contact.lift*blend,l.side*.157);solveLimb(l.a,l.b,l.c,target,Q(),V(-1,.1,l.side*.3));return {...l,contact,target};});
  for(const side of [-1,1]){const wing=bones['wing '+side],tip=bones['wing tip '+side],axis=rest.get(tip).clone().sub(rest.get(wing)).normalize(),direction=V(.08+.08*Math.sin(phase*Math.PI*2+side*Math.PI/2)*blend,-1,side*.80).normalize();rotateWorld(wing,Q().setFromUnitVectors(axis,direction));tip.rotation.x=side*.03*blend;}
  worker.root.rotation.y=-heading*Math.PI/180;worker.root.position.copy(position).add(V(distance,0,0).applyAxisAngle(V(0,1,0),-heading*Math.PI/180));worker.root.updateMatrixWorld(true);skeleton.update();state={animal:profile.id,weapon:'hands',distance,stride,phase,blend,heading,primary:0,support:'Breast low and alternating toe pushes',arms:[-1,1].map(side=>({side,planted:false,primary:false,contact:'wing',anchor:bones['wing tip '+side].getWorldPosition(V()).toArray()})),feet:footStates.map(l=>({side:l.side,planted:l.contact.planted,phase:l.contact.phase,ankle:l.c.getWorldPosition(V()).toArray(),target:worker.root.localToWorld(l.target.clone()).toArray()})),grip:null};return state;
 }
 // Fit the actual feathered body once; keep feet locked during playback.
 for(let pass=0;pass<2;pass++){let minimum=Infinity;for(let i=0;i<8;i++){raw(stride*i/8);for(const mesh of worker.parts.filter(p=>!p.name.includes('toes'))){const a=mesh.geometry.attributes.position;for(let j=0;j<a.count;j++)minimum=Math.min(minimum,mesh.getVertexPosition(j,V()).applyMatrix4(mesh.matrixWorld).y);}}height+=.008-minimum;}
 raw(0,{blend:0});return {worker,stride,at(distance,options){if(disposed)throw Error('Crawl motion disposed');validateCrawlSample(distance,options);return raw(distance,options);},diagnostics:()=>state,dispose(){if(disposed)return;disposed=true;tail.removeFromParent();skeleton.dispose();base.dispose();restore(original);worker.root.position.copy(rootState.p);worker.root.quaternion.copy(rootState.q);worker.root.scale.copy(rootState.s);worker.root.updateMatrixWorld(true);worker.skeleton.update();}};
}
